"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[39676],{39676:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<TvCard\\n  cover=\\"/assets/snippets/screen/Black(2017).jpg\\"\\n  title=\\"블랙 (2017)\\"\\n  release_date=\\"2017-10-14\\"\\n  episode_count=18\\n  genres=[\\"Fantasy\\",\\"범죄\\"]\\n  rating=2.5\\n  tags=\\"tv\\"\\n/>\\n</center>\\n\\n## Review\\n소재는 좋았으나, 구성의 치밀함과 미리 깔아 놓는 떡밥이 너무 약하다.\\n\\n특히 ```고유 번호``` 소재는 너무 빈약하고 억지스럽다.  \\n발견되어야 한다는 기준이 명확할 수 없다.\\n신체 어디까지 허용되는 것인가? 거시 세계에서의 발견만 해당하는가? 어디까지가 그 사람인가?\\n이런 요소는 사용하지 않는 것이 좋아 보인다.  \\n\\n여자 주인공은 전형적인 빌런이다. 너무 답답한 캐릭터다.\\n\\n엔딩 장면은 굳이 넣었어야 했나 하는 생각이 든다."}')}}]);